insert into public.profile (id, name, role, email, city, bio_it, bio_en, seeking_it, seeking_en, interests, avatar_url, updated_at) values ('84739ed8-5a49-483c-a474-49d4df29c546', 'Federica Gaglianone', 'Aspiring Researcher', 'federica.gaglianone@proton.me', 'Turin, Italy - Newcastle, UK', 'Mi sono formata come artista. Cinque anni di liceo artistico e poi una triennale in Nuove Tecnologie dell''Arte all''Accademia Albertina di Torino, dove ho imparato a guardare lentamente — corpi, città, superfici — e a considerare quello sguardo una forma di ricerca.
