insert into public.projects (id, year, cover_url, link_url, title_en, title_it, summary_en, summary_it, body_en, body_it, sort_order, created_at) values ('e0acfa61-c9a2-4beb-a96c-7026aa22d04e', '2026', '/projects-cover/il-bel-paese.svg', 'https://il-bel-paese.lovable.app/', 'Il Bel Paese', 'Il Bel Paese', 'An ambitious ongoing project exploring Italian cultural heritage through interactive digital storytelling — a central piece of my upcoming PhD research.', 'Un ambizioso progetto in corso che esplora il patrimonio culturale italiano attraverso storytelling digitale interattivo — un tassello centrale della mia futura ricerca di dottorato.', 'Work in progress. Il Bel Paese is shaping up to be a large-scale exploration of Italy''s cultural identity, blending interactive narrative, design, and computational tools. The project is still under active development and will continue to grow alongside my PhD trajectory.', 'Lavoro in corso. Il Bel Paese si sta delineando come un''esplorazione su larga scala dell''identità culturale italiana, intrecciando narrazione interattiva, design e strumenti computazionali. Il progetto è ancora in pieno sviluppo e continuerà a crescere insieme al mio percorso di dottorato.', '0', '2026-06-18 07:31:17.941594+00') on conflict do nothing;
insert into public.projects (id, year, cover_url, link_url, title_en, title_it, summary_en, summary_it, body_en, body_it, sort_order, created_at) values ('df03e0cc-f337-4d36-b735-ba173d8f1b83', '2025', '/projects-cover/oracolo-del-silicio.svg', 'https://github.com/feduh/oracolo-del-silicio', 'Oracolo del Silicio', 'Oracolo del Silicio', 'An interactive web work staging an oracular AI in a science-fiction Turin of the year 3000: a synthetic voice and a 3D particle cloud as a meditative, liminal device.', 'Un''opera web interattiva che mette in scena un''IA oracolare nella Torino fantascientifica dell''anno 3000: voce sintetica e nuvola di particelle 3D come dispositivo meditativo e liminale.', 'Developed as the artistic project for my BA thesis in New Art Technologies (Accademia di Belle Arti di Torino), Oracolo del Silicio translates concepts from the thesis "Anatomie Riprogrammate" — posthumanism, Eco-Horror, unstable coexistence — into an immersive experience. Two modes: an Oracle mode with low-latency streaming TTS (ElevenLabs) synchronized to a React Three Fiber particle entity, and a text Chat mode powered by GPT-4o with a RAG layer over a custom personality dataset (manuale.json). Built with Next.js (App Router), Tailwind CSS, React Three Fiber/Drei; AI and TTS logic kept server-side for security and modularity.', 'Sviluppato come progetto artistico per la tesi triennale in Nuove Tecnologie dell''Arte (Accademia di Belle Arti di Torino), Oracolo del Silicio traduce i concetti della tesi "Anatomie Riprogrammate" — postumanesimo, Eco-Horror, coesistenza instabile — in un''esperienza immersiva. Due modalità: Oracolo con sintesi vocale in streaming a bassa latenza (ElevenLabs) sincronizzata a un''entità di particelle in React Three Fiber, e Chat testuale basata su GPT-4o con uno strato RAG su un dataset di personalità custom (manuale.json). Realizzato con Next.js (App Router), Tailwind CSS, React Three Fiber/Drei; la logica di AI e TTS resta lato server per sicurezza e modularità.', '1', '2026-06-17 12:40:48.853485+00') on conflict do nothing;
insert into public.publications (id, year, authors, venue, doi, pdf_url, title_en, title_it, abstract_en, abstract_it, sort_order, created_at) values ('3ae71686-04f6-416f-a21f-f01cb8230323', '2025', 'Federica Gaglianone', 'Albertina Academy of Fine Arts, Turin — BA Thesis', NULL, 'https://f003.backblazeb2.com/file/bucket-pubblicazioni/Federica_Gaglianone-Anatomie_Riprogrammate-backblaze.pdf', 'Reprogrammed Anatomies: Biological and Technological Transformations in the Future Urban Landscape of Turin', 'Anatomie Riprogrammate: Trasformazioni Biologiche e Tecnologiche nel futuro urbano di Torino', 'BA thesis exploring the intersection between the human body, generative technologies and new media art. It investigates how algorithmic and computational processes can reprogram the perception, representation and boundaries of anatomy in contemporary artistic practice.', 'Tesi di laurea triennale che esplora l''intersezione tra corpo umano, tecnologie generative e new media art. Indaga come processi algoritmici e computazionali possano riprogrammare la percezione, la rappresentazione e i confini dell''anatomia nella pratica artistica contemporanea.', '0', '2026-07-01 09:13:12.031382+00') on conflict do nothing;
