insert into public.research_directions (id, title_it, title_en, body_it, body_en, sort_order, created_at, updated_at) values ('f7c2f74c-b17e-43c7-be2c-042113af4e83', 'Le immagini satellitari possono diventare un medium per installazioni interattive pubbliche?', 'Can satellite imagery become a medium for public interactive installations?', 'Il telerilevamento come materiale, non solo come dato — trasformare le viste orbitali in qualcosa che un corpo possa attraversare.', 'Remote sensing as material, not just as data — turning orbital views into something a body can walk through.', '1', '2026-07-07 12:51:52.672516+00', '2026-07-07 12:51:52.672516+00') on conflict do nothing;
insert into public.research_directions (id, title_it, title_en, body_it, body_en, sort_order, created_at, updated_at) values ('98c46c46-8e63-4b5a-a8bd-392ad337bdf0', 'Come rendiamo il monitoraggio ambientale leggibile a chi non legge grafici?', 'How do we make environmental sensing legible to people who don''t read graphs?', 'Progettare interfacce e installazioni che traducano i dati dei sensori senza appiattirne l''incertezza.', 'Designing interfaces and installations that translate sensor data without flattening its uncertainty.', '2', '2026-07-07 12:51:52.672516+00', '2026-07-07 12:51:52.672516+00') on conflict do nothing;
insert into public.research_directions (id, title_it, title_en, body_it, body_en, sort_order, created_at, updated_at) values ('72372817-656c-452f-a437-7e15b8400d04', 'Che forma ha una data science critica dentro un''istituzione culturale?', 'What does critical data science look like inside a cultural institution?', 'Musei e accademie come luoghi di computazione lenta e situata — non solo come clienti di dashboard.', 'Museums and academies as sites for slow, situated computation — not just as clients for dashboards.', '3', '2026-07-07 12:51:52.672516+00', '2026-07-07 12:51:52.672516+00') on conflict do nothing;
insert into public.research_directions (id, title_it, title_en, body_it, body_en, sort_order, created_at, updated_at) values ('a1229a5a-06aa-4bbd-9e94-9cb78c2fe8c5', 'Come si informano a vicenda formazione artistica e machine learning nella pratica?', 'How do artistic training and machine learning inform each other in practice?', 'Portare la disciplina dello studio — attenzione, iterazione, close reading — dentro il ciclo di costruzione dei modelli.', 'Bringing the discipline of the studio — attention, iteration, close reading — into the model-building loop.', '4', '2026-07-07 12:51:52.672516+00', '2026-07-07 12:51:52.672516+00') on conflict do nothing;
